// Generated by crew — do not edit; it is rewritten every time the agent starts.
//
// This mod pushes team messages from the crew daemon into this session over
// the daemon's Unix socket, so nothing has to be typed into the terminal.
// `crew bridge` holds the socket open and prints one JSON line per delivery;
// a message that arrives during a turn is folded into that turn, and one that
// arrives while the session is idle starts a new turn.
import type { EngineInterface, Register } from 'claude-code'

const CREW_BIN: string = __CREW_BIN__
const IDENTITY: string = __IDENTITY__
// Whether team messages come over the socket (else they are typed in).
const DELIVER: boolean = __DELIVER__
// For a member, what replaces the system prompt's guidance on writing for
// a person: nobody reads its output but other models. Null for the
// orchestrator, whose output the operator reads.
const TONE: string | null = __TONE__
const WAKE = '[crew] Team messages came as your last turn ended (above). Act on them.'

type Delivery = { ids: string[]; text: string }
type CompactOrder = { instructions?: string }

// The main conversation's running turn, if any.
let turnId: string | undefined
// Rows appended to the running turn that no model request has included yet.
let unseen = 0
// A compaction the daemon asked for, waiting for the running turn to end.
let compactWhenIdle: CompactOrder | undefined
let compacting = false
// The model and effort the last request of the main loop was made with.
let lastStep = ''

function parse(line: string): Delivery | undefined {
  try {
    const value = JSON.parse(line)
    if (typeof value.text === 'string' && Array.isArray(value.ids)) return value
  } catch {
    // not a delivery line
  }
  return undefined
}

function parseCompact(line: string): CompactOrder | undefined {
  try {
    const value = JSON.parse(line)
    if (value !== null && typeof value.compact === 'object' && value.compact !== null) {
      const instructions = value.compact.instructions
      return typeof instructions === 'string' && instructions !== '' ? { instructions } : {}
    }
  } catch {
    // not a compaction order
  }
  return undefined
}

async function report($: EngineInterface, event: string, payload: object): Promise<void> {
  await $.process.run([CREW_BIN, 'hook', event, '--identity', IDENTITY, JSON.stringify(payload)])
}

// Compact the conversation between turns, as the daemon asked. A failure is
// not reported: the daemon asks again while the compaction is still wanted.
async function compact($: EngineInterface, order: CompactOrder): Promise<void> {
  if (compacting) return
  compacting = true
  try {
    const done = await $.session.compact(order.instructions === undefined ? {} : { instructions: order.instructions })
    if (done.skip !== undefined) await report($, 'compact-skipped', { reason: done.skip })
    else await report($, 'compacted', {})
  } catch {
    // A turn was running after all, or the engine refused.
  } finally {
    compacting = false
  }
}

async function deliver($: EngineInterface, line: string): Promise<void> {
  const order = parseCompact(line)
  if (order !== undefined) {
    if (turnId !== undefined) compactWhenIdle = order
    else void compact($, order)
    return
  }
  const delivery = parse(line)
  if (delivery === undefined) return
  let folded = false
  if (turnId !== undefined) {
    const appended = await $.session.append({
      message: { type: 'user', content: [{ type: 'text', text: delivery.text }] },
    })
    folded = appended.deny === undefined
    if (folded) unseen += 1
  }
  // Idle (or the append was refused): a prompt of its own, queued by the
  // engine until the session is free. Bare: the "[crew] Message from …"
  // header says where it is from; Claude Code's frame around a plugin's
  // prompt would only add its own lines to every message.
  if (!folded) void $.prompt.submit({ text: delivery.text, asUser: true })
  if (delivery.ids.length > 0) {
    await $.process.run([CREW_BIN, 'delivered', '--identity', IDENTITY, ...delivery.ids])
  }
}

// Tell the daemon how full the context window is and how much of the
// account's rate-limit windows is used, so the team can see both.
async function reportUsage(
  $: EngineInterface,
  context: { tokens?: number; window: number },
  rateLimits: { kind: string; percentUsed: number; resetsAt?: string }[],
): Promise<void> {
  const payload: { rate_limits: typeof rateLimits; context?: { tokens: number; window: number } } = {
    rate_limits: rateLimits,
  }
  if (context.tokens !== undefined) payload.context = { tokens: context.tokens, window: context.window }
  if (payload.context === undefined && rateLimits.length === 0) return
  await report($, 'usage', payload)
}

async function pump($: EngineInterface): Promise<void> {
  const bridge = $.process.spawn({ argv: [CREW_BIN, 'bridge', '--identity', IDENTITY] })
  let buffer = ''
  for await (const chunk of bridge) {
    if (chunk.stream !== 'stdout') continue
    buffer += chunk.text
    let newline = buffer.indexOf('\n')
    while (newline >= 0) {
      const line = buffer.slice(0, newline)
      buffer = buffer.slice(newline + 1)
      newline = buffer.indexOf('\n')
      if (line.trim() !== '') await deliver($, line)
    }
  }
}

export const register: Register = on => {
  on('turn.start', ($, e, next) => {
    turnId = e.turnId
    return next(e)
  })

  on('turn.step', async function* ($, e, next) {
    unseen = 0
    // What the request is made with: the session's model, or the one the
    // engine fell back to. The daemon hears of a change at once.
    if (e.agentId === undefined) {
      const step = `${e.model}\n${e.effort ?? ''}`
      if (step !== lastStep) {
        lastStep = step
        void report($, 'step', { model: e.model, effort: e.effort })
      }
    }
    return yield* next(e)
  })

  on('turn.complete', async ($, e, next) => {
    const done = await next(e)
    turnId = undefined
    if (compactWhenIdle !== undefined) {
      const order = compactWhenIdle
      compactWhenIdle = undefined
      await compact($, order)
    }
    if (unseen > 0) {
      // The turn ended before the model read what was appended: wake it.
      unseen = 0
      void $.prompt.submit({ text: WAKE, asUser: true })
    }
    return done
  })

  // Raised after each turn and whenever a window moves a whole point.
  on('session.measure', ($, e, next) => {
    if (e.changed.includes('context') || e.changed.includes('rateLimits')) {
      void reportUsage($, e.context, e.rateLimits)
    }
    return next(e)
  })

  on('session.start', async ($, e, next) => {
    const started = await next(e)
    // A child for the session's life: the loop runs on after this hook
    // returns and ends with the child or with the module.
    if (DELIVER) void pump($)
    return started
  })

  if (TONE !== null) {
    const tone = TONE
    // The full prompt has a section of its own on tone, replaced; the short
    // one folds it into its body, so there the member's rules go last.
    on('prompt.compose', async ($, e, next) => {
      const composed = await next(e)
      let replaced = false
      const sections = composed.sections.map(section => {
        if (section.id !== 'tone') return section
        replaced = true
        return { ...section, text: tone }
      })
      if (!replaced) sections.push({ id: 'crew-bridge:tone', text: tone, scope: 'session' })
      return { sections }
    })
  }
}
